def read(p,k):return p.evaluate('k=>JSON.parse(localStorage.getItem("dujia-prototype-"+k)||"null")',k)
def store(p):return p.evaluate('JSON.stringify({...localStorage})')
def fail(p,k):p.evaluate('k=>sessionStorage.setItem("dujia-prototype-fail-next",k)',k)
def landed(p,id):p.wait_for_url('**/'+id+'.html*')
def nav(p,name):p.locator('body>nav').get_by_role('button',name=name,exact=True).click()
def link(p,name):p.get_by_role('button',name=name,exact=True).click()
def date(p,field,value):
 p.locator('[name='+field+']').click();p.locator('dialog input[type=date]').fill(value);p.get_by_role('button',name='使用这个日期',exact=True).click();expect(p.locator('dialog')).to_have_count(0)
def stage(p,steps,name):
 if name=='today-related-diary':expect(p.get_by_role('button',name='纪念日当天日记',exact=True)).to_be_visible()
 p.evaluate('document.fonts.ready');expect(p.locator('[aria-busy=true]')).to_have_count(0);p.locator('.screen').evaluate('s=>Promise.all(s.getAnimations().map(a=>a.finished.catch(()=>{})))');steps.append(dict(step=name,url=p.url,snapshot={k:read(p,k)for k in ['records','moments','anniversaries','capsules','reminder-reads','relationship','session']}));print('STEP '+name,flush=True)
 if name in ['today-related-diary','sealed-private','opened-photo','deleted-capsule-kept-moment','empty-reminders-kept-originals']:p.screenshot(path=str(SHOTS/(name+'.png')),full_page=True)
def remove(p,kind):
 p.locator('#more').click();p.get_by_role('button',name='删除'+kind,exact=True).click()

