with sync_playwright()as pw:
 b=pw.chromium.launch(headless=True,executable_path=r'C:\Program Files\Google\Chrome\Application\chrome.exe');c=b.new_context(viewport=dict(width=390,height=844),timezone_id='Asia/Shanghai');p=c.new_page();p.set_default_timeout(5000);p.set_default_navigation_timeout(10000);errors=[];steps=[];navigations=[];p.on('pageerror',lambda e:errors.append(str(e)));p.on('framenavigated',lambda f:navigations.append(f.url)if f==p.main_frame else None)
